contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // Call withdraw with a nonzero amount from this contract (which is not the owner) and check that
    // if it reverts then neither depositsCount nor the contract balance changed.
    function run(uint amount) public payable {
        require(amount > 0);
        // Observe before-state
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        // Invoke withdraw and record whether it reverted
        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe after-state
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        // If the call reverted, it must not have changed depositsCount or balance.
        assert(!reverted || (afterCount == beforeCount && afterBal == beforeBal));
    }
    receive() external payable {}
}

